    await save(2,true);expect((await collections.applyCollection(context,command)).replayed).toBe(true);expect((await db.query('SELECT choices,reference_list_id FROM hs_data_fields WHERE tenant_id=$1 AND collection=$2',[context.tenantId,proposal.id])).rows).toEqual([{choices:[],reference_list_id:listId}]);expect((await db.query('SELECT * FROM hs_data_collection_grants WHERE tenant_id=$1 AND collection=$2',[context.tenantId,proposal.id])).rows).toEqual([]);
