    const item={id:crypto.randomUUID(),code:'FINANCE',label:'Finance',order:0,deprecated:false,translations:{}},selection={expectedVersion:0,definition:{tenantId:context.tenantId,id:crypto.randomUUID(),version:1,name:'Synthetic departments',items:[item]}},review=await lists.previewReferenceList(context,selection),command={previewId:review.previewId,reviewHash:review.reviewHash,selection,operationId:crypto.randomUUID()};
