  it('queries one hundred thousand synthetic records through indexed fifty-item permission-filtered pages',async()=>{
    const {context,authority}=await sharedFixture();await db.query("INSERT INTO hs_data_records(id,tenant_id,collection,name,created_by,updated_by) SELECT gen_random_uuid(),$1,'organisations','Scale record '||lpad(i::text,6,'0'),$2,$2 FROM generate_series(1,100000) i",[context.tenantId,localActor.id]);await db.query('ANALYZE hs_data_records');let observed:{sql:string;values:unknown[]}|undefined;const observing=new Repository({...db,transaction:fn=>db.transaction(tx=>fn({query:async<T>(sql:string,values?:unknown[])=>{if(sql.startsWith('SELECT r.* FROM hs_data_records r WHERE'))observed={sql,values:values??[]};return tx.query<T>(sql,values);}}))}),records=new SharedRecordRepository(observing,authority),timings:number[]=[];let at=performance.now();const first=await records.list(context,{collection:'organisations',query:'Scale record 099'});timings.push(performance.now()-at);expect(first.results).toHaveLength(50);expect(first.results[0].name).toBe('Scale record 099000');expect(first.nextCursor).toBeTruthy();const search=observed!;at=performance.now();const second=await records.list(context,{collection:'organisations',query:'Scale record 099',cursor:first.nextCursor!});timings.push(performance.now()-at);expect(second.results).toHaveLength(50);expect(second.results[0].name).toBe('Scale record 099050');expect(new Set([...first.results,...second.results].map(v=>v.id)).size).toBe(100);const plan=await db.query<Record<string,unknown>>('EXPLAIN (ANALYZE,BUFFERS,FORMAT JSON) '+search.sql,search.values);expect(JSON.stringify(plan.rows)).toMatch(/hs_data_record_(prefix|order)/);await mkdir('artifacts',{recursive:true});await writeFile('artifacts/shared-record-query.json',JSON.stringify({scope:'Synthetic isolated PostgreSQL; not a live tenant or approved p95 budget',totalRecords:100000,pageSize:50,pagesVerified:2,uniqueReturned:100,roundTripMs:timings,plan:plan.rows},null,2));
  },120000);
